<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';
import {api,attachment,dateToday} from './api';
const me=ref<any>(null),children=ref<any[]>([]),selected=ref(''),assignments=ref<any[]>([]),imports=ref<any[]>([]),draft=ref<any>(null),devices=ref<any[]>([]);
const page=ref('today'),loginMode=ref('child'),password=ref(''),code=ref(''),error=ref(''),notice=ref(''),busy=ref(false),date=ref(dateToday()),pending=ref(false),text=ref(''),fileInput=ref<HTMLInputElement>(),targetIds=ref<string[]>([]),name=ref(''),grade=ref(''),pairing=ref(''),pairChild=ref(''),preview=ref(''),edit=ref<any>(null);
const parent=computed(()=>me.value?.role==='parent'),child=computed(()=>children.value.find(c=>c.id===selected.value)),done=computed(()=>assignments.value.filter(a=>!!a.completed).length),groups=computed(()=>assignments.value.reduce<Record<string,any[]>>((g,a)=>{(g[a.subject]??=[]).push(a);return g;},Object.create(null)));
const status:Record<string,string>={queued:'等待分析',running:'正在分析',review:'待审核',failed:'分析失败',published:'已发布'};
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作失败';}finally{busy.value=false;}}
function expired(){me.value=null;children.value=[];assignments.value=[];draft.value=null;imports.value=[];}
async function loadAssignments(){if(selected.value)assignments.value=await api(`/assignments?childId=${selected.value}&date=${date.value}&pending=${pending.value}`);else assignments.value=[];}
async function loadImports(){if(parent.value)imports.value=await api('/imports');}
async function init(){me.value=await api('/me');children.value=await api('/children');if(!children.value.some(c=>c.id===selected.value))selected.value=children.value[0]?.id??'';if(!targetIds.value.length&&selected.value)targetIds.value=[selected.value];await loadAssignments();await loadImports();}
async function login(){await act(async()=>{const s=await api(loginMode.value==='parent'?'/auth/login':'/auth/pair',{method:'POST',body:JSON.stringify(loginMode.value==='parent'?{password:password.value}:{code:code.value})});localStorage.setItem('homework_token',s.token);password.value='';code.value='';await init();});}
async function logout(){await act(async()=>{await api('/auth/logout',{method:'POST'});localStorage.removeItem('homework_token');expired();});}
async function changePage(p:string){page.value=p;await act(async()=>{await loadAssignments();if(p==='imports')await loadImports();if(p==='family')devices.value=await api('/devices');});}
async function toggle(a:any){await act(async()=>{await api(`/assignments/${a.id}/complete`,{method:'PUT',body:JSON.stringify({completed:!a.completed,revision:a.revision})});await loadAssignments();});}
async function upload(){await act(async()=>{const f=new FormData();f.set('text',text.value);f.set('workDate',date.value);f.set('childIds',JSON.stringify(targetIds.value));for(const file of Array.from(fileInput.value?.files??[]))f.append('files',file);const r=await api('/imports',{method:'POST',body:f});text.value='';if(fileInput.value)fileInput.value.value='';await loadImports();draft.value=await api(`/imports/${r.id}`);notice.value='已提交，分析结果需家长审核后发布';});}
async function openDraft(id:string){await act(async()=>{draft.value=await api(`/imports/${id}`);if(!draft.value.result)draft.value.result={items:[],notices:[]};});}
async function saveDraft(){await api(`/imports/${draft.value.id}`,{method:'PUT',body:JSON.stringify({version:draft.value.version,result:draft.value.result,childIds:draft.value.child_ids,workDate:draft.value.work_date})});draft.value=await api(`/imports/${draft.value.id}`);await loadImports();}
async function publish(){await act(async()=>{await saveDraft();await api(`/imports/${draft.value.id}/publish`,{method:'POST',body:JSON.stringify({version:draft.value.version})});draft.value=null;await loadImports();await loadAssignments();notice.value='已发布到孩子端';});}
async function retry(id:string){await act(async()=>{await api(`/imports/${id}/retry`,{method:'POST'});draft.value=null;await loadImports();});}
async function withdraw(id:string){if(!confirm('撤回后，孩子端作业及该批完成记录将移除。确定撤回？'))return;await act(async()=>{await api(`/imports/${id}/withdraw`,{method:'POST'});draft.value=null;await loadImports();await loadAssignments();});}
async function addChild(){await act(async()=>{const c=await api('/children',{method:'POST',body:JSON.stringify({name:name.value,grade:grade.value})});name.value='';grade.value='';selected.value=c.id;await init();});}
async function makePair(){await act(async()=>{const r=await api('/pairing',{method:'POST',body:JSON.stringify({childId:pairChild.value||null})});pairing.value=r.code;});}
async function revoke(id:string){await act(async()=>{await api(`/devices/${id}`,{method:'DELETE'});devices.value=await api('/devices');});}
async function showAttachment(id:string){await act(async()=>{closePreview();preview.value=await attachment(id);});}
function closePreview(){if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';}
async function details(a:any){await act(async()=>{const attachments=await api(`/assignments/${a.id}/attachments`);edit.value={...a,dueDate:a.due_date,warning:'',attachments};});}
async function saveAssignment(){await act(async()=>{await api(`/assignments/${edit.value.id}`,{method:'PUT',body:JSON.stringify(edit.value)});edit.value=null;await loadAssignments();notice.value='已更新，孩子需重新确认完成';});}
function blankItem(){return {subject:'语文',content:'',dueDate:null,materials:'',warning:''};}
function printPage(){window.print();}
let timer:ReturnType<typeof setInterval>;let refreshing=false;
onMounted(()=>{window.addEventListener('session-expired',expired);if(localStorage.getItem('homework_token'))void act(init);timer=setInterval(async()=>{if(!me.value||busy.value||refreshing||document.hidden)return;refreshing=true;try{if(page.value==='imports'){await loadImports();if(draft.value&&['queued','running'].includes(draft.value.status))draft.value=await api(`/imports/${draft.value.id}`);}else if(page.value==='today')await loadAssignments();}catch(e){error.value=e instanceof Error?e.message:'同步失败';}finally{refreshing=false;}},5000);});
onUnmounted(()=>{clearInterval(timer);window.removeEventListener('session-expired',expired);closePreview();});
</script>

<template>
 <div v-if="!me" class="login-shell">
  <section class="login-card"><div class="brand-icon">福</div><p class="eyebrow">HOMEWORK, MADE SIMPLE</p><h1>fufuyun-homework</h1><p class="muted">把零散的消息，变成清晰的一天。</p>
   <div class="tabs"><button :class="{active:loginMode==='child'}" @click="loginMode='child'">孩子设备配对</button><button :class="{active:loginMode==='parent'}" @click="loginMode='parent'">家长登录</button></div>
   <form @submit.prevent="login"><label v-if="loginMode==='parent'">家长密码<input v-model="password" type="password" autocomplete="current-password" required></label><label v-else>12 位配对码<input v-model="code" placeholder="由家长在家庭设置中生成" maxlength="12" autocomplete="off" required></label><button class="primary wide" :disabled="busy">{{busy?'正在连接…':'进入作业助手'}}</button></form>
   <p class="muted small">家长可通过网页管理，也可使用微信小程序。孩子配对后无需微信账号。</p><p v-if="error" role="alert" class="error">{{error}}</p>
  </section><aside class="login-art"><span>慢慢来，<br>一件一件完成。</span><div class="art-card">✓ 读一篇喜欢的文章<br>□ 写下今天的小收获<br>□ 留一点时间给自己</div></aside>
 </div>
 <div v-else class="app-shell">
  <aside class="sidebar no-print"><a href="#" class="brand" @click.prevent="changePage('today')"><span class="brand-icon">福</span>福福云<span class="brand-sub">家庭作业助手</span></a><p class="eyebrow">{{parent?'家长工作台':'我的学习空间'}}</p><nav><button :class="{active:page==='today'}" @click="changePage('today')">▦ 今日作业</button><button v-if="parent" :class="{active:page==='imports'}" @click="changePage('imports')">＋ 整理与发布</button><button v-if="parent" :class="{active:page==='family'}" @click="changePage('family')">⌂ 家庭与设备</button></nav><div class="sidebar-note">每天进步一点点，<br>也记得好好休息。</div><button class="quiet" @click="logout">{{parent?'退出登录':'解除本机登录'}}</button></aside>
  <main><header class="topbar no-print"><span>{{parent?'我的家庭':'专注此刻，完成一件小事'}}</span><span class="badge">{{parent?'家长模式':'孩子模式'}}</span></header>
   <p v-if="error" role="alert" class="error no-print">{{error}}</p><p v-if="notice" role="status" class="success no-print">{{notice}}</p>
   <template v-if="page==='today'">
    <div class="page-heading"><div><p class="eyebrow">A LITTLE PROGRESS EVERY DAY</p><h1>{{child?.name?child.name+'的作业':'今天，从这里开始'}}</h1><p class="muted">{{pending?'把还没完成的小任务，一件件做好。':'整理好今天的任务，给自己留一点自由时间。'}}</p></div><button class="outline no-print" @click="printPage">打印清单 / 存储 PDF</button></div>
    <div class="toolbar no-print"><label>孩子<select v-model="selected" @change="act(loadAssignments)"><option v-for="c in children" :value="c.id" :key="c.id">{{c.name}}</option></select></label><label>作业日期<input v-model="date" type="date" @change="act(loadAssignments)"></label><label class="check"><input v-model="pending" type="checkbox" @change="act(loadAssignments)">所有未完成</label><button class="quiet" :disabled="busy" @click="act(loadAssignments)">刷新</button></div>
    <section class="progress-card"><div><span class="badge">{{pending?'待办清单':'今日进度'}}</span><h2>{{assignments.length?`${done} / ${assignments.length} 项已勾选完成`:'还没有作业，享受轻松时光'}}</h2><p>{{assignments.length&&done===assignments.length?'今天的任务已全部勾选，辛苦啦！':'不着急，从最想完成的一项开始。'}}</p><small>完成状态由孩子勾选，不代表家长已检查。</small></div><div class="progress-ring" :style="{'--progress':`${assignments.length?done/assignments.length*100:0}%`}"><span>{{assignments.length?Math.round(done/assignments.length*100):0}}<small>%</small></span></div></section>
    <section v-if="!children.length" class="empty">还没有添加孩子。请先在“家庭与设备”添加。</section>
    <div v-for="(items,subject) in groups" :key="subject" class="subject-group"><h2><span class="subject-mark">{{String(subject).slice(0,1)}}</span>{{subject}} <small>{{items?.length}} 项任务</small></h2><article v-for="a in items" :key="a.id" class="assignment" :class="{completed:a.completed}"><button class="completion" :aria-label="a.completed?'取消完成':'标记完成'" :aria-pressed="!!a.completed" :disabled="busy" @click="toggle(a)">{{a.completed?'✓':''}}</button><div class="assignment-body"><span v-if="a.updated" class="update-label">内容有更新，请重新确认</span><p class="assignment-text">{{a.content}}</p><p v-if="a.materials" class="muted">准备：{{a.materials}}</p><div class="meta"><span v-if="pending">所属 {{a.work_date}}</span><span v-if="a.due_date">截止 {{a.due_date}}</span><span v-else>未指定截止日期</span><span>{{a.completed?'已勾选完成':'待完成'}}</span></div></div><button class="quiet no-print" @click="details(a)">{{parent?'详情 / 编辑':'查看详情'}}</button></article></div>
    <div v-if="children.length&&!assignments.length" class="empty">这里还没有任务。家长发布后会自动出现在这里。</div>
   </template>
   <template v-if="page==='imports'&&parent"><div class="page-heading"><div><p class="eyebrow">LESS SORTING, MORE FAMILY TIME</p><h1>把消息，整理成作业</h1><p class="muted">导入 → Kimi 整理 → 你来审核 → 发布给孩子</p></div></div><p v-if="!me.aiConfigured" class="error">Kimi 密钥尚未配置。导入会提示分析失败，仍可手动编辑并发布。</p>
    <section class="panel"><h2>导入微信消息</h2><div class="toolbar"><label>作业日期<input v-model="date" type="date" required></label><fieldset><legend>分配给孩子</legend><label v-for="c in children" :key="c.id" class="check"><input v-model="targetIds" type="checkbox" :value="c.id">{{c.name}}</label></fieldset></div><label>消息文字<textarea v-model="text" rows="6" maxlength="50000" placeholder="粘贴老师的作业消息，可包含多条。没有文字时也可上传截图。"></textarea></label><label>截图或导出文件<input ref="fileInput" type="file" multiple accept=".jpg,.jpeg,.png,.webp,.txt,.json"></label><p class="muted small">最多 5 个文件，每个不超过 8MB。支持截图、UTF-8 TXT 与约定格式 JSON；不直接读取微信群历史。提交的消息与截图将发送给 Kimi 分析。</p><button class="primary" :disabled="busy||!children.length||!targetIds.length" @click="upload">{{busy?'提交中…':'交给 Kimi 整理'}}</button></section>
    <section class="panel"><h2>最近导入</h2><div v-if="!imports.length" class="empty">还没有导入记录</div><div v-for="j in imports" :key="j.id" class="import-row"><div><strong>{{j.work_date}}</strong><p class="muted source-snippet">{{j.source_text||'图片消息'}}</p><p v-if="j.error" class="error">{{j.error}}</p></div><span class="badge">{{status[j.status]}}</span><button class="outline" @click="openDraft(j.id)">查看{{j.status==='review'?' / 审核':''}}</button></div></section>
   </template>
   <template v-if="page==='family'&&parent"><div class="page-heading"><div><p class="eyebrow">OUR LITTLE TEAM</p><h1>家庭与设备</h1><p class="muted">一个家庭，多份独立的小进步。</p></div></div><section class="panel"><h2>孩子档案</h2><div class="child-list"><div v-for="c in children" :key="c.id" class="child-card"><span class="avatar">{{c.name.slice(0,1)}}</span><div><strong>{{c.name}}</strong><p class="muted">{{c.grade||'未设置年级 / 班级'}}</p></div></div></div><form class="toolbar" @submit.prevent="addChild"><label>孩子昵称<input v-model="name" required maxlength="40"></label><label>年级 / 班级<input v-model="grade" maxlength="40"></label><button class="primary" :disabled="busy">添加孩子</button></form></section><section class="panel"><h2>绑定孩子的 iPad</h2><p class="muted">在孩子设备打开同一个网址，输入一次性配对码即可。</p><div class="toolbar"><label>设备用途<select v-model="pairChild"><option value="">共用设备：可切换全部孩子</option><option v-for="c in children" :value="c.id" :key="c.id">{{c.name}}的专用设备</option></select></label><button class="primary" :disabled="busy||!children.length" @click="makePair">生成配对码</button></div><p v-if="pairing" class="pair-code">{{pairing}}<small>10 分钟有效，仅可使用一次</small></p><h3>已配对设备</h3><div v-for="d in devices" :key="d.id" class="import-row"><span>{{d.child_id?children.find(c=>c.id===d.child_id)?.name+'的设备':'共用设备'}} · {{d.created_at}}</span><button class="outline" @click="revoke(d.id)">撤销访问</button></div><p v-if="!devices.length" class="muted">暂无设备，配对完成后重新进入本页刷新。</p></section></template>
   <footer>福福云 · 陪伴每一个小小的进步<span class="no-print">联网时每 5 秒同步 · 操作成功后才记录完成</span></footer>
  </main>
 </div>
 <div v-if="draft" class="modal-backdrop no-print"><section class="modal" role="dialog" aria-modal="true" aria-label="审核作业"><header><h2>审核作业 · {{status[draft.status]}}</h2><button class="quiet" @click="draft=null">关闭</button></header><p v-if="error" class="error" role="alert">{{error}}</p><details><summary>原始消息与附件</summary><pre>{{draft.source_text||'无文字'}}</pre><button v-for="f in draft.attachments" :key="f.id" class="outline" @click="showAttachment(f.id)">{{f.name}}</button></details><p v-if="draft.error" class="error">{{draft.error}}</p><template v-if="['review','failed'].includes(draft.status)"><label>所属日期<input v-model="draft.work_date" type="date"></label><fieldset><legend>分配孩子</legend><label v-for="c in children" :key="c.id" class="check"><input v-model="draft.child_ids" type="checkbox" :value="c.id">{{c.name}}</label></fieldset><p v-if="draft.result?.notices?.length" class="success">通知（不会作为作业发布）：{{draft.result.notices.join('；')}}</p><p class="muted">请与原消息核对日期、页码、题号和孩子；相似作业不会自动覆盖已有内容。</p><article v-for="(i,index) in draft.result?.items" :key="index" class="draft-item"><label>科目<input v-model="i.subject" maxlength="30"></label><label>作业要求<textarea v-model="i.content" rows="3" maxlength="3000"></textarea></label><div class="toolbar"><label>截止日期<input :value="i.dueDate??''" type="date" @input="i.dueDate=($event.target as HTMLInputElement).value||null"></label><label>准备材料<input v-model="i.materials" maxlength="500"></label></div><p v-if="i.warning" class="error">待确认：{{i.warning}}</p><button class="quiet" @click="draft.result.items.splice(index,1)">删除这一项</button></article><button class="outline" @click="draft.result.items.push(blankItem())">添加作业</button><div class="modal-actions"><button v-if="draft.status==='failed'" class="outline" :disabled="busy" @click="retry(draft.id)">重新分析</button><button class="outline" :disabled="busy" @click="act(async()=>{await saveDraft();notice='草稿已保存'})">保存草稿</button><button class="primary" :disabled="busy||!draft.result?.items?.length" @click="publish">保存并发布</button></div></template><template v-else-if="draft.status==='published'"><p>已发布给孩子。修改个别作业请到“今日作业”；整批重新审核可先撤回。</p><button class="outline" @click="withdraw(draft.id)">撤回整批作业</button></template><p v-else>正在排队或分析，请稍候，结果会自动更新。</p></section></div>
 <div v-if="edit" class="modal-backdrop no-print"><section class="modal" role="dialog" aria-modal="true" aria-label="作业详情"><header><h2>{{edit.subject}} · 作业详情</h2><button class="quiet" @click="edit=null">关闭</button></header><p v-if="error" class="error">{{error}}</p><template v-if="parent"><label>科目<input v-model="edit.subject"></label><label>要求<textarea v-model="edit.content" rows="6"></textarea></label><label>截止日期<input :value="edit.dueDate??''" type="date" @input="edit.dueDate=($event.target as HTMLInputElement).value||null"></label><label>材料<input v-model="edit.materials"></label><p class="muted">更新后将取消原完成状态，提醒孩子重新确认。只修改当前孩子的这一项。</p><button class="primary" :disabled="busy" @click="saveAssignment">保存修改</button></template><template v-else><p class="assignment-text">{{edit.content}}</p><p v-if="edit.materials">准备：{{edit.materials}}</p><p>截止：{{edit.due_date||'未指定'}}</p></template><h3>原始附件</h3><button v-for="f in edit.attachments" :key="f.id" class="outline" @click="showAttachment(f.id)">{{f.name}}</button><p v-if="!edit.attachments.length" class="muted">无附件</p></section></div>
 <div v-if="preview" class="modal-backdrop preview no-print"><button class="primary" @click="closePreview">关闭附件</button><iframe :src="preview" title="原始附件预览"></iframe></div>
</template>
